export async function getChapterMdxComponents(
  bookSlug: string,
  sectionSlug: string,
  chapterSlug: string,
): Promise<ChapterMdxComponents> {
  const route = `${bookSlug}/${sectionSlug}/${chapterSlug}`;
  return chapterComponentLoaders[route]?.() ?? {};
}
